vec4 effect(vec2 uv) {
  float fr = floor(uTime * 18.0);
  vec2 j = (vec2(hash(vec2(fr, 2.0)), hash(vec2(fr, 7.0))) - 0.5) * 0.006 * uAmount;
  vec3 c = blurAt(uv + j, 0.003).rgb;
  c = mix(c, c * vec3(1.12, 1.0, 0.78) + vec3(0.04, 0.02, 0.0), uAmount);
  c += (hash(uv * 900.0 + fr) - 0.5) * 0.12 * uAmount;
  vec2 d = (uv - 0.5) * vec2(uRatio, 1.0);
  c *= 1.0 - smoothstep(0.4, 1.0, length(d)) * 0.8 * uAmount;
  return vec4(c, getColor(uv).a);
}
